Value.Calculation:
Let ( [
		~iso = GetValue ( Substitute ( $datumNivelacije ; "T" ; Char ( 13 ) ) ; 1 )
	];

	If ( Length ( ~iso ) < 10 ;
		Get ( CurrentDate ) ;
		Date (
			GetAsNumber ( Middle ( ~iso ; 6 ; 2 ) ) ;
			GetAsNumber ( Right ( ~iso ; 2 ) ) ;
			GetAsNumber ( Left ( ~iso ; 4 ) )
		)
	)
)

Let ( [
		~rows = epSQLResultRowCount ( "rs_max" ) ;
		~last = If ( ~rows = 0 ; "" ; epSQLResult ( 0 ; 0 ; "rs_max" ) ) ;
		~serial = If ( Length ( ~last ) < 9 ; 0 ; GetAsNumber ( Middle ( ~last ; 3 ; 3 ) ) )
	];

	"N-" & Right ( "00" & ( ~serial + 1 ) ; 3 ) & "-" & $yy
)

epSQLExecute (
	"INSERT INTO Nivelacija" &
	" ( PrimaryKey, BrojNivelacije, DatumNivelacije, Status, NacinIzmjene, Napomena," &
	"   ForeignKeyCompanyID, AzurirajStandardnuCijenu )" &
	" VALUES ( ?, ?, " & epSQLQuoteDate ( $datum ) & ", ?, ?, ?, ?, ? )" ;
	"" ;
	$nivelacijaId ;
	$broj ;
	"Otvorena" ;
	$nacin ;
	$napomena ;
	$companyId ;
	If ( $azurirajStandardnu ; 1 ; 0 )
)

Response_SetData ( JSONSetElement ( "{}" ;
	[ "nivelacijaId" ; $nivelacijaId ; JSONString ] ;
	[ "brojNivelacije" ; $broj ; JSONString ] ;
	[ "nacinIzmjene" ; $nacin ; JSONString ] ;
	[ "datumNivelacije" ; Year ( $datum ) & "-" & Right ( "0" & Month ( $datum ) ; 2 ) & "-" & Right ( "0" & Day ( $datum ) ; 2 ) ; JSONString ]
) )
